import { env } from '@/lib/env'

/**
 * Vector tile infrastructure for the map. The archive is generated by the
 * forked hk-pmtiles-generation GitHub Actions workflow and served from the
 * fork's GitHub Pages; the URL doubles as the cache key for browser tile
 * caches, so a new release tag invalidates everyone (same scheme hkbus uses).
 * Overridable with NEXT_PUBLIC_MAP_TILE_ARCHIVE_URL (see lib/env.ts).
 */
export const MAP_TILE_ARCHIVE_URL = env.NEXT_PUBLIC_MAP_TILE_ARCHIVE_URL

export const MAP_TILE_PROTOCOL = 'pmtiles://'

export const MAP_GLYPHS_URL = env.NEXT_PUBLIC_MAP_GLYPHS_URL

// Same-origin sprite mirror fetched at build time by
// scripts/fetch-map-data.mjs, so icon rendering does not depend on a
// third-party host surviving the user's network.
export const MAP_SPRITE_URL = env.NEXT_PUBLIC_MAP_SPRITE_URL

export const MAP_ATTRIBUTION_HTML =
  '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'

/**
 * Dev-only tile archive health check. A silently stale or 404 archive looks
 * like a working map with missing tiles, so surface it loud in dev instead.
 */
export async function checkMapTileArchiveHealth(
  url = MAP_TILE_ARCHIVE_URL
): Promise<{ ok: true } | { ok: false; reason: 'missing' | 'stale'; ageDays?: number }> {
  try {
    const res = await fetch(url, { method: 'HEAD', cache: 'no-store' })
    if (res.status === 404) return { ok: false, reason: 'missing' }
    if (!res.ok) return { ok: false, reason: 'missing' }
    const lastModified = res.headers.get('last-modified')
    if (!lastModified) return { ok: true }
    const ageDays = Math.floor((Date.now() - new Date(lastModified).getTime()) / 86_400_000)
    // The workflow refreshes every ~4 days; older than two weeks means the
    // scheduled Action likely stopped running (fork inactivity / disabled).
    if (ageDays > 14) return { ok: false, reason: 'stale', ageDays }
    return { ok: true }
  } catch {
    // Network check failing is not evidence the archive is broken; the map
    // load itself will surface real fetch errors.
    return { ok: true }
  }
}
